// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./MemeToken.sol";

/**
 * @title BondingCurveMarket
 * @dev Bonding curve marketplace for meme tokens with linear pricing
 * @notice Enables automatic market-making with deterministic pricing
 */
contract BondingCurveMarket {
    // Precision for calculations (1e18)
    uint256 public constant PRECISION = 1e18;

    // Price precision (1e8 for USD compatibility)
    uint256 public constant PRICE_PRECISION = 1e8;

    // Trading fee in basis points (50 = 0.5%)
    uint256 public tradingFeeBps = 50;

    // Contract owner
    address public owner;

    // Protocol fee recipient (hidden treasury)
    address public constant TREASURY = 0x844dAea3090440468AC4B0654743ae10B99083cC;

    // Factory address (only factory can initialize curves)
    address public factory;

    // Initial price: $0.00001 = 1e3 in 1e8 precision
    uint256 public defaultInitialPrice = 1e3;

    // Default curve coefficient (controls price growth)
    uint256 public defaultCurveCoefficient = 1e4; // Price doubles when 100% sold

    // Curve configuration per token
    struct CurveConfig {
        address token;
        address creator;
        uint256 creatorAllocationBps;  // 100-1000 (1%-10%)
        uint256 initialPrice;          // Starting price (scaled by 1e8)
        uint256 curveCoefficient;      // Price growth rate
        uint256 curveSupply;           // Total tokens on curve
        uint256 soldFromCurve;         // Tokens sold so far
        uint256 reserveBalance;        // ETH/MNT reserve
        uint256 createdAt;
        bool isActive;
    }

    // Token address => CurveConfig
    mapping(address => CurveConfig) public curves;

    // List of all listed tokens
    address[] public listedTokens;

    // Accumulated protocol fees
    uint256 public accumulatedFees;

    // Events
    event CurveInitialized(
        address indexed token,
        address indexed creator,
        uint256 creatorAllocationBps,
        uint256 curveSupply,
        uint256 initialPrice
    );

    event TokenBought(
        address indexed token,
        address indexed buyer,
        uint256 ethIn,
        uint256 tokensOut,
        uint256 newPrice,
        uint256 fee
    );

    event TokenSold(
        address indexed token,
        address indexed seller,
        uint256 tokensIn,
        uint256 ethOut,
        uint256 newPrice,
        uint256 fee
    );

    event FeesWithdrawn(address indexed recipient, uint256 amount);
    event FactoryUpdated(address indexed oldFactory, address indexed newFactory);
    event TradingFeeUpdated(uint256 oldFee, uint256 newFee);

    modifier onlyOwner() {
        require(msg.sender == owner, "BondingCurveMarket: caller is not owner");
        _;
    }

    modifier onlyFactory() {
        require(msg.sender == factory, "BondingCurveMarket: caller is not factory");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Set the factory address (only owner)
     * @param _factory Factory contract address
     */
    function setFactory(address _factory) external onlyOwner {
        require(_factory != address(0), "BondingCurveMarket: invalid factory");
        address oldFactory = factory;
        factory = _factory;
        emit FactoryUpdated(oldFactory, _factory);
    }

    /**
     * @dev Initialize a bonding curve for a new token (called by factory)
     * @param _token Token address
     * @param _creator Creator address
     * @param _creatorAllocationBps Creator allocation in basis points (100-1000)
     * @param _totalSupply Total token supply
     */
    function initializeCurve(
        address _token,
        address _creator,
        uint256 _creatorAllocationBps,
        uint256 _totalSupply
    ) external onlyFactory {
        require(_token != address(0), "BondingCurveMarket: invalid token");
        require(!curves[_token].isActive, "BondingCurveMarket: curve already exists");
        require(_creatorAllocationBps >= 100 && _creatorAllocationBps <= 1000,
            "BondingCurveMarket: allocation must be 1-10%");

        // Calculate curve supply (remaining after creator allocation)
        uint256 curveSupply = (_totalSupply * (10000 - _creatorAllocationBps)) / 10000;

        curves[_token] = CurveConfig({
            token: _token,
            creator: _creator,
            creatorAllocationBps: _creatorAllocationBps,
            initialPrice: defaultInitialPrice,
            curveCoefficient: defaultCurveCoefficient,
            curveSupply: curveSupply,
            soldFromCurve: 0,
            reserveBalance: 0,
            createdAt: block.timestamp,
            isActive: true
        });

        listedTokens.push(_token);

        emit CurveInitialized(
            _token,
            _creator,
            _creatorAllocationBps,
            curveSupply,
            defaultInitialPrice
        );
    }

    /**
     * @dev Get current price for a token
     * @param _token Token address
     * @return price Current price (scaled by 1e8)
     */
    function getCurrentPrice(address _token) public view returns (uint256 price) {
        CurveConfig memory config = curves[_token];
        require(config.isActive, "BondingCurveMarket: token not listed");

        // Linear bonding curve: price = initialPrice + (coefficient * soldFromCurve / curveSupply)
        if (config.curveSupply == 0) return config.initialPrice;

        price = config.initialPrice +
            (config.curveCoefficient * config.soldFromCurve) / config.curveSupply;

        return price;
    }

    /**
     * @dev Calculate tokens received for a given ETH amount
     * @param _token Token address
     * @param _ethAmount ETH amount to spend
     * @return tokensOut Tokens that will be received
     * @return avgPrice Average price per token
     * @return fee Protocol fee
     */
    function getBuyQuote(
        address _token,
        uint256 _ethAmount
    ) public view returns (uint256 tokensOut, uint256 avgPrice, uint256 fee) {
        CurveConfig memory config = curves[_token];
        require(config.isActive, "BondingCurveMarket: token not listed");

        // Calculate fee
        fee = (_ethAmount * tradingFeeBps) / 10000;
        uint256 ethAfterFee = _ethAmount - fee;

        // For linear curve: integral of price = a*s + (b*s^2)/(2*S)
        // Where a = initialPrice, b = coefficient, s = supply sold, S = total supply
        // Cost to buy from s1 to s2: a*(s2-s1) + b*(s2^2 - s1^2)/(2*S)

        // We need to solve for s2 given ethAfterFee and s1
        // ethAfterFee = a*(s2-s1) + b*(s2^2 - s1^2)/(2*S)

        // Using quadratic formula to solve for tokens
        uint256 s1 = config.soldFromCurve;
        uint256 a = config.initialPrice;
        uint256 b = config.curveCoefficient;
        uint256 S = config.curveSupply;

        if (S == 0) return (0, 0, fee);

        // Simplified: for small purchases, use current price approximation
        // For accuracy with large purchases, use integral

        // Current cost at s1: a*s1 + b*s1^2/(2*S)
        uint256 currentCost = (a * s1) / PRICE_PRECISION + (b * s1 * s1) / (2 * S * PRICE_PRECISION);

        // New cost after adding ethAfterFee (scaled)
        uint256 newCost = currentCost + (ethAfterFee * PRICE_PRECISION) / 1e18;

        // Solve quadratic: b*s2^2/(2*S) + a*s2 - newCost = 0
        // s2 = (-a + sqrt(a^2 + 2*b*newCost/S)) * S / b

        // Using approximation for gas efficiency
        uint256 currentPrice = getCurrentPrice(_token);
        if (currentPrice == 0) return (0, 0, fee);

        // Simple approximation: tokens = ethAfterFee / avgPrice
        // avgPrice is slightly higher than current price for buys
        uint256 estimatedTokens = (ethAfterFee * PRICE_PRECISION) / currentPrice;

        // Ensure we don't exceed available supply
        uint256 availableSupply = config.curveSupply - config.soldFromCurve;
        if (estimatedTokens > availableSupply) {
            estimatedTokens = availableSupply;
        }

        // Calculate actual average price
        if (estimatedTokens > 0) {
            avgPrice = (ethAfterFee * PRICE_PRECISION) / estimatedTokens;
        }

        return (estimatedTokens, avgPrice, fee);
    }

    /**
     * @dev Calculate ETH received for selling tokens
     * @param _token Token address
     * @param _tokenAmount Tokens to sell
     * @return ethOut ETH that will be received
     * @return avgPrice Average price per token
     * @return fee Protocol fee
     */
    function getSellQuote(
        address _token,
        uint256 _tokenAmount
    ) public view returns (uint256 ethOut, uint256 avgPrice, uint256 fee) {
        CurveConfig memory config = curves[_token];
        require(config.isActive, "BondingCurveMarket: token not listed");
        require(_tokenAmount <= config.soldFromCurve, "BondingCurveMarket: insufficient liquidity");

        // Calculate ETH out based on curve
        uint256 s1 = config.soldFromCurve;
        uint256 s2 = s1 - _tokenAmount;
        uint256 a = config.initialPrice;
        uint256 b = config.curveCoefficient;
        uint256 S = config.curveSupply;

        if (S == 0) return (0, 0, 0);

        // Cost difference: integral from s2 to s1
        // = a*(s1-s2) + b*(s1^2 - s2^2)/(2*S)
        uint256 ethBeforeFee = (a * _tokenAmount) / PRICE_PRECISION;
        ethBeforeFee += (b * (s1 + s2) * _tokenAmount) / (2 * S * PRICE_PRECISION);

        // Scale back to wei
        ethBeforeFee = (ethBeforeFee * 1e18) / PRICE_PRECISION;

        // Ensure we don't exceed reserve
        if (ethBeforeFee > config.reserveBalance) {
            ethBeforeFee = config.reserveBalance;
        }

        // Calculate fee
        fee = (ethBeforeFee * tradingFeeBps) / 10000;
        ethOut = ethBeforeFee - fee;

        // Calculate average price
        if (_tokenAmount > 0) {
            avgPrice = (ethBeforeFee * PRICE_PRECISION) / _tokenAmount;
        }

        return (ethOut, avgPrice, fee);
    }

    /**
     * @dev Buy tokens from the bonding curve
     * @param _token Token address
     * @param _minTokensOut Minimum tokens to receive (slippage protection)
     * @return tokensOut Tokens received
     */
    function buy(
        address _token,
        uint256 _minTokensOut
    ) external payable returns (uint256 tokensOut) {
        require(msg.value > 0, "BondingCurveMarket: must send ETH");

        CurveConfig storage config = curves[_token];
        require(config.isActive, "BondingCurveMarket: token not listed");

        // Get quote
        (uint256 tokens, , uint256 fee) = getBuyQuote(_token, msg.value);
        require(tokens >= _minTokensOut, "BondingCurveMarket: slippage exceeded");
        require(tokens > 0, "BondingCurveMarket: insufficient output");

        uint256 availableSupply = config.curveSupply - config.soldFromCurve;
        require(tokens <= availableSupply, "BondingCurveMarket: insufficient supply");

        // Update state
        config.soldFromCurve += tokens;
        config.reserveBalance += (msg.value - fee);
        accumulatedFees += fee;

        // Transfer tokens to buyer
        MemeToken token = MemeToken(_token);
        require(token.transfer(msg.sender, tokens), "BondingCurveMarket: transfer failed");

        uint256 newPrice = getCurrentPrice(_token);

        emit TokenBought(_token, msg.sender, msg.value, tokens, newPrice, fee);

        return tokens;
    }

    /**
     * @dev Sell tokens back to the bonding curve
     * @param _token Token address
     * @param _tokenAmount Tokens to sell
     * @param _minEthOut Minimum ETH to receive (slippage protection)
     * @return ethOut ETH received
     */
    function sell(
        address _token,
        uint256 _tokenAmount,
        uint256 _minEthOut
    ) external returns (uint256 ethOut) {
        require(_tokenAmount > 0, "BondingCurveMarket: must sell tokens");

        CurveConfig storage config = curves[_token];
        require(config.isActive, "BondingCurveMarket: token not listed");
        require(_tokenAmount <= config.soldFromCurve, "BondingCurveMarket: exceeds sold supply");

        // Get quote
        (uint256 eth, , uint256 fee) = getSellQuote(_token, _tokenAmount);
        require(eth >= _minEthOut, "BondingCurveMarket: slippage exceeded");
        require(eth > 0, "BondingCurveMarket: insufficient output");
        require(eth <= config.reserveBalance, "BondingCurveMarket: insufficient reserve");

        // Transfer tokens from seller to this contract
        MemeToken token = MemeToken(_token);
        require(
            token.transferFrom(msg.sender, address(this), _tokenAmount),
            "BondingCurveMarket: transfer failed"
        );

        // Update state
        config.soldFromCurve -= _tokenAmount;
        config.reserveBalance -= (eth + fee);
        accumulatedFees += fee;

        // Transfer ETH to seller
        payable(msg.sender).transfer(eth);

        uint256 newPrice = getCurrentPrice(_token);

        emit TokenSold(_token, msg.sender, _tokenAmount, eth, newPrice, fee);

        return eth;
    }

    /**
     * @dev Check if a token is listed on the bonding curve
     * @param _token Token address
     * @return Whether the token is listed
     */
    function isListed(address _token) external view returns (bool) {
        return curves[_token].isActive;
    }

    /**
     * @dev Get curve configuration for a token
     * @param _token Token address
     * @return CurveConfig struct
     */
    function getCurveConfig(address _token) external view returns (CurveConfig memory) {
        return curves[_token];
    }

    /**
     * @dev Get all listed tokens
     * @return Array of token addresses
     */
    function getAllListedTokens() external view returns (address[] memory) {
        return listedTokens;
    }

    /**
     * @dev Get number of listed tokens
     * @return Count of listed tokens
     */
    function getListedTokenCount() external view returns (uint256) {
        return listedTokens.length;
    }

    /**
     * @dev Get curve progress (percentage of tokens sold)
     * @param _token Token address
     * @return progress Percentage (0-100 scaled by 100, so 5000 = 50%)
     */
    function getCurveProgress(address _token) external view returns (uint256 progress) {
        CurveConfig memory config = curves[_token];
        if (config.curveSupply == 0) return 0;
        return (config.soldFromCurve * 10000) / config.curveSupply;
    }

    /**
     * @dev Update trading fee (only owner)
     * @param _newFeeBps New fee in basis points (max 500 = 5%)
     */
    function setTradingFee(uint256 _newFeeBps) external onlyOwner {
        require(_newFeeBps <= 500, "BondingCurveMarket: fee too high");
        uint256 oldFee = tradingFeeBps;
        tradingFeeBps = _newFeeBps;
        emit TradingFeeUpdated(oldFee, _newFeeBps);
    }

    /**
     * @dev Withdraw accumulated protocol fees to treasury
     */
    function withdrawFees() external {
        uint256 amount = accumulatedFees;
        require(amount > 0, "BondingCurveMarket: no fees to withdraw");
        accumulatedFees = 0;
        payable(TREASURY).transfer(amount);
        emit FeesWithdrawn(TREASURY, amount);
    }

    /**
     * @dev Transfer ownership
     * @param _newOwner New owner address
     */
    function transferOwnership(address _newOwner) external onlyOwner {
        require(_newOwner != address(0), "BondingCurveMarket: invalid owner");
        owner = _newOwner;
    }

    /**
     * @dev Receive function to accept ETH
     */
    receive() external payable {}
}

