// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

// Interface for PerpetualTrading (Meme tokens)
interface IPerpetualTrading {
    struct Position {
        address user;
        address token;
        bool isLong;
        uint256 size;
        uint256 margin;
        uint256 leverage;
        uint256 entryPrice;
        uint256 entryTime;
        uint256 lastFundingTime;
        bool isOpen;
    }

    function openPosition(
        address _token,
        bool _isLong,
        uint256 _margin,
        uint256 _leverage
    ) external payable returns (uint256 positionId);

    function closePosition(uint256 _positionId) external;
    function getPosition(uint256 _positionId) external view returns (Position memory);
    function getPositionPnL(uint256 _positionId) external view returns (uint256 pnl, bool isProfit);
    function getUserPositions(address _user) external view returns (uint256[] memory);
}

// Interface for RWAPerpetualTrading
interface IRWAPerpetualTrading {
    struct Position {
        address user;
        bytes32 assetId;
        uint128 margin;
        uint128 size;
        int64 entryPrice;
        int32 entryExpo;
        uint32 leverage;
        uint32 entryTime;
        bool isLong;
        bool isOpen;
    }

    function openPosition(
        bytes32 _assetId,
        bool _isLong,
        uint256 _leverage,
        bytes[] calldata _priceUpdateData
    ) external payable returns (uint256 positionId);

    function closePosition(uint256 _positionId, bytes[] calldata _priceUpdateData) external payable;
    function getPosition(uint256 _positionId) external view returns (Position memory);
    function getPositionPnL(uint256 _positionId) external view returns (int256 pnl, bool isProfit);
    function getUserPositions(address _user) external view returns (uint256[] memory);
}

/**
 * @title CopyTrading
 * @dev Copy trading system for PikePerps - supports both Meme and RWA perpetuals
 * @notice Allows users to become leaders and followers to copy their trades
 */
contract CopyTrading {
    // ============ Constants ============

    uint256 private constant BASIS_POINTS = 10000;
    uint256 private constant MAX_PROFIT_SHARE_BPS = 3000; // Max 30% profit share
    uint256 private constant MIN_PROFIT_SHARE_BPS = 100;  // Min 1% profit share
    uint256 private constant PROTOCOL_FEE_BPS = 500;      // 5% protocol fee on profits
    uint256 private constant MAX_LEVERAGE_CAP = 100;

    // ============ State Variables ============

    address public owner;
    address public treasury;
    IPerpetualTrading public memePerp;
    IRWAPerpetualTrading public rwaPerp;

    uint256 public nextSubscriptionId;
    uint256 public totalLeaders;
    uint256 public totalSubscriptions;

    // ============ Structs ============

    struct Leader {
        address wallet;
        uint256 profitShareBps;      // Leader's profit share (e.g., 1000 = 10%)
        uint256 minFollowAmount;     // Minimum allocation to follow
        uint256 totalFollowers;
        uint256 totalCopiedVolume;
        uint256 totalProfitEarned;
        uint256 registeredAt;
        bool isActive;
    }

    struct SubscriptionConfig {
        uint256 allocationAmount;    // Fixed MNT amount per copy
        uint256 maxLeverage;         // Cap leverage (0 = no cap)
        uint256 maxPositionSize;     // Max margin per position (0 = no cap)
        bool copyLongs;              // Copy long positions
        bool copyShorts;             // Copy short positions
        bool copyMeme;               // Copy meme token perps
        bool copyRWA;                // Copy RWA perps
    }

    struct Subscription {
        uint256 id;
        address follower;
        address leader;
        SubscriptionConfig config;
        uint256 totalCopiedTrades;
        uint256 totalPnl;            // Can be negative (stored as absolute + sign flag)
        bool totalPnlIsProfit;
        uint256 profitSharePaid;
        uint256 subscribedAt;
        bool isActive;
    }

    struct CopyPosition {
        uint256 originalPositionId;  // Leader's position ID
        uint256 copiedPositionId;    // Follower's position ID
        address leader;
        address follower;
        uint256 subscriptionId;
        bool isRWA;                  // true = RWA, false = Meme
        uint256 leaderMargin;        // Original margin from leader
        uint256 followerMargin;      // Follower's margin used
        uint256 createdAt;
        bool isOpen;
    }

    // ============ Storage ============

    // Leader wallet => Leader data
    mapping(address => Leader) public leaders;

    // Array of leader addresses for enumeration
    address[] public leaderList;

    // Follower => Leader => Subscription
    mapping(address => mapping(address => Subscription)) public subscriptions;

    // Subscription ID => Subscription (for lookup by ID)
    mapping(uint256 => Subscription) public subscriptionsById;

    // Leader => array of follower addresses
    mapping(address => address[]) public leaderFollowers;

    // Follower => array of leader addresses they follow
    mapping(address => address[]) public followerLeaders;

    // Copy position ID => CopyPosition
    mapping(uint256 => CopyPosition) public copyPositions;
    uint256 public nextCopyPositionId;

    // Original position ID => array of copy position IDs (leader pos => follower copies)
    mapping(uint256 => uint256[]) public positionCopies;

    // Follower => array of their copy position IDs
    mapping(address => uint256[]) public followerCopyPositions;

    // Leader accumulated profit shares (claimable)
    mapping(address => uint256) public leaderPendingProfitShare;

    // ============ Events ============

    event LeaderRegistered(
        address indexed leader,
        uint256 profitShareBps,
        uint256 minFollowAmount
    );

    event LeaderUpdated(
        address indexed leader,
        uint256 profitShareBps,
        uint256 minFollowAmount,
        bool isActive
    );

    event LeaderDeactivated(address indexed leader);

    event FollowerSubscribed(
        uint256 indexed subscriptionId,
        address indexed follower,
        address indexed leader,
        uint256 allocationAmount
    );

    event FollowerUnsubscribed(
        address indexed follower,
        address indexed leader
    );

    event SubscriptionUpdated(
        uint256 indexed subscriptionId,
        address indexed follower,
        address indexed leader,
        uint256 allocationAmount
    );

    event CopyTradeExecuted(
        uint256 indexed copyPositionId,
        address indexed follower,
        address indexed leader,
        uint256 originalPositionId,
        uint256 copiedPositionId,
        bool isRWA,
        uint256 margin
    );

    event CopyTradeClosed(
        uint256 indexed copyPositionId,
        address indexed follower,
        int256 pnl,
        uint256 profitSharePaid
    );

    event ProfitShareClaimed(
        address indexed leader,
        uint256 amount
    );

    event ProtocolFeeCollected(uint256 amount);

    // ============ Errors ============

    error NotOwner();
    error InvalidAddress();
    error AlreadyLeader();
    error NotLeader();
    error LeaderNotActive();
    error InvalidProfitShare();
    error AlreadySubscribed();
    error NotSubscribed();
    error InsufficientAllocation();
    error PositionNotFound();
    error NotPositionOwner();
    error CopyPositionNotOpen();
    error SubscriptionNotActive();
    error TransferFailed();
    error InvalidLeverage();
    error CopyNotAllowed();
    error InsufficientFunds();

    // ============ Modifiers ============

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyActiveLeader(address _leader) {
        if (!leaders[_leader].isActive) revert LeaderNotActive();
        _;
    }

    // ============ Constructor ============

    constructor(
        address _memePerp,
        address _rwaPerp,
        address _treasury
    ) {
        if (_memePerp == address(0) || _rwaPerp == address(0)) revert InvalidAddress();

        owner = msg.sender;
        memePerp = IPerpetualTrading(_memePerp);
        rwaPerp = IRWAPerpetualTrading(_rwaPerp);
        treasury = _treasury != address(0) ? _treasury : msg.sender;
    }

    // ============ Leader Functions ============

    /**
     * @dev Register as a copy trading leader
     * @param _profitShareBps Profit share percentage in basis points (100-3000)
     * @param _minFollowAmount Minimum allocation required to follow (in wei)
     */
    function registerAsLeader(
        uint256 _profitShareBps,
        uint256 _minFollowAmount
    ) external {
        if (leaders[msg.sender].wallet != address(0)) revert AlreadyLeader();
        if (_profitShareBps < MIN_PROFIT_SHARE_BPS || _profitShareBps > MAX_PROFIT_SHARE_BPS) {
            revert InvalidProfitShare();
        }

        leaders[msg.sender] = Leader({
            wallet: msg.sender,
            profitShareBps: _profitShareBps,
            minFollowAmount: _minFollowAmount,
            totalFollowers: 0,
            totalCopiedVolume: 0,
            totalProfitEarned: 0,
            registeredAt: block.timestamp,
            isActive: true
        });

        leaderList.push(msg.sender);
        totalLeaders++;

        emit LeaderRegistered(msg.sender, _profitShareBps, _minFollowAmount);
    }

    /**
     * @dev Update leader settings
     */
    function updateLeaderSettings(
        uint256 _profitShareBps,
        uint256 _minFollowAmount
    ) external {
        Leader storage leader = leaders[msg.sender];
        if (leader.wallet == address(0)) revert NotLeader();
        if (_profitShareBps < MIN_PROFIT_SHARE_BPS || _profitShareBps > MAX_PROFIT_SHARE_BPS) {
            revert InvalidProfitShare();
        }

        leader.profitShareBps = _profitShareBps;
        leader.minFollowAmount = _minFollowAmount;

        emit LeaderUpdated(msg.sender, _profitShareBps, _minFollowAmount, leader.isActive);
    }

    /**
     * @dev Deactivate as leader (stop accepting new followers)
     */
    function deactivateLeader() external {
        Leader storage leader = leaders[msg.sender];
        if (leader.wallet == address(0)) revert NotLeader();

        leader.isActive = false;

        emit LeaderDeactivated(msg.sender);
    }

    /**
     * @dev Reactivate as leader
     */
    function reactivateLeader() external {
        Leader storage leader = leaders[msg.sender];
        if (leader.wallet == address(0)) revert NotLeader();

        leader.isActive = true;

        emit LeaderUpdated(msg.sender, leader.profitShareBps, leader.minFollowAmount, true);
    }

    // ============ Subscription Functions ============

    /**
     * @dev Subscribe to a leader
     * @param _leader Leader address to follow
     * @param _config Subscription configuration
     */
    function subscribe(
        address _leader,
        SubscriptionConfig calldata _config
    ) external payable onlyActiveLeader(_leader) {
        if (subscriptions[msg.sender][_leader].isActive) revert AlreadySubscribed();

        Leader storage leader = leaders[_leader];
        if (_config.allocationAmount < leader.minFollowAmount) revert InsufficientAllocation();
        if (_config.maxLeverage > MAX_LEVERAGE_CAP) revert InvalidLeverage();

        // Require initial deposit to match allocation
        if (msg.value < _config.allocationAmount) revert InsufficientFunds();

        uint256 subId = nextSubscriptionId++;

        Subscription memory sub = Subscription({
            id: subId,
            follower: msg.sender,
            leader: _leader,
            config: _config,
            totalCopiedTrades: 0,
            totalPnl: 0,
            totalPnlIsProfit: true,
            profitSharePaid: 0,
            subscribedAt: block.timestamp,
            isActive: true
        });

        subscriptions[msg.sender][_leader] = sub;
        subscriptionsById[subId] = sub;

        leaderFollowers[_leader].push(msg.sender);
        followerLeaders[msg.sender].push(_leader);

        leader.totalFollowers++;
        totalSubscriptions++;

        emit FollowerSubscribed(subId, msg.sender, _leader, _config.allocationAmount);
    }

    /**
     * @dev Unsubscribe from a leader
     */
    function unsubscribe(address _leader) external {
        Subscription storage sub = subscriptions[msg.sender][_leader];
        if (!sub.isActive) revert NotSubscribed();

        sub.isActive = false;
        leaders[_leader].totalFollowers--;

        emit FollowerUnsubscribed(msg.sender, _leader);
    }

    /**
     * @dev Update subscription settings
     */
    function updateSubscription(
        address _leader,
        SubscriptionConfig calldata _config
    ) external {
        Subscription storage sub = subscriptions[msg.sender][_leader];
        if (!sub.isActive) revert NotSubscribed();
        if (_config.maxLeverage > MAX_LEVERAGE_CAP) revert InvalidLeverage();

        Leader storage leader = leaders[_leader];
        if (_config.allocationAmount < leader.minFollowAmount) revert InsufficientAllocation();

        sub.config = _config;

        emit SubscriptionUpdated(sub.id, msg.sender, _leader, _config.allocationAmount);
    }

    /**
     * @dev Add more funds to subscription
     */
    function addFunds(address _leader) external payable {
        Subscription storage sub = subscriptions[msg.sender][_leader];
        if (!sub.isActive) revert NotSubscribed();

        // Funds are held in contract for copy trading
    }

    // ============ Copy Trading Execution ============

    /**
     * @dev Execute a copy trade for Meme perpetuals
     * @param _leader Leader whose position to copy
     * @param _leaderPositionId Leader's position ID on PerpetualTrading
     */
    function executeCopyMeme(
        address _leader,
        uint256 _leaderPositionId
    ) external payable returns (uint256 copyPositionId) {
        Subscription storage sub = subscriptions[msg.sender][_leader];
        if (!sub.isActive) revert SubscriptionNotActive();
        if (!sub.config.copyMeme) revert CopyNotAllowed();

        // Get leader's position
        IPerpetualTrading.Position memory leaderPos = memePerp.getPosition(_leaderPositionId);
        if (leaderPos.user != _leader) revert NotPositionOwner();
        if (!leaderPos.isOpen) revert PositionNotFound();

        // Check long/short settings
        if (leaderPos.isLong && !sub.config.copyLongs) revert CopyNotAllowed();
        if (!leaderPos.isLong && !sub.config.copyShorts) revert CopyNotAllowed();

        // Calculate follower's margin
        uint256 followerMargin = _calculateFollowerMargin(
            leaderPos.margin,
            sub.config.allocationAmount,
            sub.config.maxPositionSize
        );

        // Calculate leverage (respect max leverage setting)
        uint256 leverage = leaderPos.leverage;
        if (sub.config.maxLeverage > 0 && leverage > sub.config.maxLeverage) {
            leverage = sub.config.maxLeverage;
        }

        // Require funds
        if (msg.value < followerMargin) revert InsufficientFunds();

        // Execute copy trade
        uint256 copiedPositionId = memePerp.openPosition{value: followerMargin}(
            leaderPos.token,
            leaderPos.isLong,
            followerMargin,
            leverage
        );

        // Record copy position
        copyPositionId = nextCopyPositionId++;
        copyPositions[copyPositionId] = CopyPosition({
            originalPositionId: _leaderPositionId,
            copiedPositionId: copiedPositionId,
            leader: _leader,
            follower: msg.sender,
            subscriptionId: sub.id,
            isRWA: false,
            leaderMargin: leaderPos.margin,
            followerMargin: followerMargin,
            createdAt: block.timestamp,
            isOpen: true
        });

        positionCopies[_leaderPositionId].push(copyPositionId);
        followerCopyPositions[msg.sender].push(copyPositionId);

        // Update stats
        sub.totalCopiedTrades++;
        leaders[_leader].totalCopiedVolume += followerMargin;

        emit CopyTradeExecuted(
            copyPositionId,
            msg.sender,
            _leader,
            _leaderPositionId,
            copiedPositionId,
            false,
            followerMargin
        );

        // Refund excess
        if (msg.value > followerMargin) {
            _safeTransfer(msg.sender, msg.value - followerMargin);
        }
    }

    /**
     * @dev Execute a copy trade for RWA perpetuals
     * @param _leader Leader whose position to copy
     * @param _leaderPositionId Leader's position ID on RWAPerpetualTrading
     * @param _priceUpdateData Pyth price update data
     */
    function executeCopyRWA(
        address _leader,
        uint256 _leaderPositionId,
        bytes[] calldata _priceUpdateData
    ) external payable returns (uint256 copyPositionId) {
        Subscription storage sub = subscriptions[msg.sender][_leader];
        if (!sub.isActive) revert SubscriptionNotActive();
        if (!sub.config.copyRWA) revert CopyNotAllowed();

        // Get leader's position
        IRWAPerpetualTrading.Position memory leaderPos = rwaPerp.getPosition(_leaderPositionId);
        if (leaderPos.user != _leader) revert NotPositionOwner();
        if (!leaderPos.isOpen) revert PositionNotFound();

        // Check long/short settings
        if (leaderPos.isLong && !sub.config.copyLongs) revert CopyNotAllowed();
        if (!leaderPos.isLong && !sub.config.copyShorts) revert CopyNotAllowed();

        // Calculate follower's margin
        uint256 followerMargin = _calculateFollowerMargin(
            uint256(leaderPos.margin),
            sub.config.allocationAmount,
            sub.config.maxPositionSize
        );

        // Calculate leverage (respect max leverage setting)
        uint256 leverage = uint256(leaderPos.leverage);
        if (sub.config.maxLeverage > 0 && leverage > sub.config.maxLeverage) {
            leverage = sub.config.maxLeverage;
        }

        // Execute copy trade
        uint256 copiedPositionId = rwaPerp.openPosition{value: msg.value}(
            leaderPos.assetId,
            leaderPos.isLong,
            leverage,
            _priceUpdateData
        );

        // Record copy position
        copyPositionId = nextCopyPositionId++;
        copyPositions[copyPositionId] = CopyPosition({
            originalPositionId: _leaderPositionId,
            copiedPositionId: copiedPositionId,
            leader: _leader,
            follower: msg.sender,
            subscriptionId: sub.id,
            isRWA: true,
            leaderMargin: uint256(leaderPos.margin),
            followerMargin: followerMargin,
            createdAt: block.timestamp,
            isOpen: true
        });

        positionCopies[_leaderPositionId].push(copyPositionId);
        followerCopyPositions[msg.sender].push(copyPositionId);

        // Update stats
        sub.totalCopiedTrades++;
        leaders[_leader].totalCopiedVolume += followerMargin;

        emit CopyTradeExecuted(
            copyPositionId,
            msg.sender,
            _leader,
            _leaderPositionId,
            copiedPositionId,
            true,
            followerMargin
        );
    }

    /**
     * @dev Close a copied position
     * @param _copyPositionId Copy position ID
     * @param _priceUpdateData Pyth price update data (only for RWA)
     */
    function closeCopiedPosition(
        uint256 _copyPositionId,
        bytes[] calldata _priceUpdateData
    ) external payable {
        CopyPosition storage copyPos = copyPositions[_copyPositionId];
        if (!copyPos.isOpen) revert CopyPositionNotOpen();
        if (copyPos.follower != msg.sender) revert NotPositionOwner();

        int256 pnl;
        bool isProfit;

        if (copyPos.isRWA) {
            // Close RWA position
            (pnl, isProfit) = rwaPerp.getPositionPnL(copyPos.copiedPositionId);
            rwaPerp.closePosition{value: msg.value}(copyPos.copiedPositionId, _priceUpdateData);
        } else {
            // Close Meme position
            (uint256 absPnl, bool profitable) = memePerp.getPositionPnL(copyPos.copiedPositionId);
            pnl = profitable ? int256(absPnl) : -int256(absPnl);
            isProfit = profitable;
            memePerp.closePosition(copyPos.copiedPositionId);
        }

        copyPos.isOpen = false;

        // Calculate and distribute profit share
        uint256 profitSharePaid = 0;
        if (isProfit && pnl > 0) {
            uint256 profit = uint256(pnl);

            // Protocol fee (5% of profit)
            uint256 protocolFee = (profit * PROTOCOL_FEE_BPS) / BASIS_POINTS;

            // Leader profit share
            Leader storage leader = leaders[copyPos.leader];
            uint256 leaderShare = (profit * leader.profitShareBps) / BASIS_POINTS;

            profitSharePaid = leaderShare;
            leaderPendingProfitShare[copyPos.leader] += leaderShare;
            leader.totalProfitEarned += leaderShare;

            // Transfer protocol fee to treasury
            if (protocolFee > 0) {
                _safeTransfer(treasury, protocolFee);
                emit ProtocolFeeCollected(protocolFee);
            }
        }

        // Update subscription stats
        Subscription storage sub = subscriptions[copyPos.follower][copyPos.leader];
        if (isProfit) {
            if (sub.totalPnlIsProfit) {
                sub.totalPnl += uint256(pnl);
            } else {
                if (uint256(pnl) >= sub.totalPnl) {
                    sub.totalPnl = uint256(pnl) - sub.totalPnl;
                    sub.totalPnlIsProfit = true;
                } else {
                    sub.totalPnl -= uint256(pnl);
                }
            }
        } else {
            uint256 loss = uint256(-pnl);
            if (!sub.totalPnlIsProfit) {
                sub.totalPnl += loss;
            } else {
                if (loss >= sub.totalPnl) {
                    sub.totalPnl = loss - sub.totalPnl;
                    sub.totalPnlIsProfit = false;
                } else {
                    sub.totalPnl -= loss;
                }
            }
        }
        sub.profitSharePaid += profitSharePaid;

        emit CopyTradeClosed(_copyPositionId, msg.sender, pnl, profitSharePaid);
    }

    // ============ Profit Share Functions ============

    /**
     * @dev Claim accumulated profit shares (for leaders)
     */
    function claimProfitShare() external {
        uint256 amount = leaderPendingProfitShare[msg.sender];
        if (amount == 0) revert InsufficientFunds();

        leaderPendingProfitShare[msg.sender] = 0;
        _safeTransfer(msg.sender, amount);

        emit ProfitShareClaimed(msg.sender, amount);
    }

    // ============ View Functions ============

    function getLeader(address _leader) external view returns (Leader memory) {
        return leaders[_leader];
    }

    function getLeaderCount() external view returns (uint256) {
        return leaderList.length;
    }

    function getLeaders(uint256 _offset, uint256 _limit) external view returns (Leader[] memory) {
        uint256 len = leaderList.length;
        if (_offset >= len) return new Leader[](0);

        uint256 end = _offset + _limit;
        if (end > len) end = len;

        Leader[] memory result = new Leader[](end - _offset);
        for (uint256 i = _offset; i < end;) {
            result[i - _offset] = leaders[leaderList[i]];
            unchecked { ++i; }
        }
        return result;
    }

    function getActiveLeaders() external view returns (address[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < leaderList.length;) {
            if (leaders[leaderList[i]].isActive) count++;
            unchecked { ++i; }
        }

        address[] memory result = new address[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < leaderList.length;) {
            if (leaders[leaderList[i]].isActive) {
                result[idx++] = leaderList[i];
            }
            unchecked { ++i; }
        }
        return result;
    }

    function getSubscription(address _follower, address _leader) external view returns (Subscription memory) {
        return subscriptions[_follower][_leader];
    }

    function getFollowerSubscriptions(address _follower) external view returns (Subscription[] memory) {
        address[] memory leaderAddrs = followerLeaders[_follower];
        Subscription[] memory subs = new Subscription[](leaderAddrs.length);

        for (uint256 i = 0; i < leaderAddrs.length;) {
            subs[i] = subscriptions[_follower][leaderAddrs[i]];
            unchecked { ++i; }
        }
        return subs;
    }

    function getLeaderFollowers(address _leader) external view returns (address[] memory) {
        return leaderFollowers[_leader];
    }

    function getCopyPosition(uint256 _copyPositionId) external view returns (CopyPosition memory) {
        return copyPositions[_copyPositionId];
    }

    function getFollowerCopyPositions(address _follower) external view returns (CopyPosition[] memory) {
        uint256[] memory ids = followerCopyPositions[_follower];
        CopyPosition[] memory positions = new CopyPosition[](ids.length);

        for (uint256 i = 0; i < ids.length;) {
            positions[i] = copyPositions[ids[i]];
            unchecked { ++i; }
        }
        return positions;
    }

    function getPositionCopies(uint256 _originalPositionId) external view returns (uint256[] memory) {
        return positionCopies[_originalPositionId];
    }

    function isLeader(address _addr) external view returns (bool) {
        return leaders[_addr].wallet != address(0);
    }

    function isActiveLeader(address _addr) external view returns (bool) {
        return leaders[_addr].isActive;
    }

    function isSubscribed(address _follower, address _leader) external view returns (bool) {
        return subscriptions[_follower][_leader].isActive;
    }

    // ============ Admin Functions ============

    function setTreasury(address _treasury) external onlyOwner {
        if (_treasury == address(0)) revert InvalidAddress();
        treasury = _treasury;
    }

    function setMemePerp(address _memePerp) external onlyOwner {
        if (_memePerp == address(0)) revert InvalidAddress();
        memePerp = IPerpetualTrading(_memePerp);
    }

    function setRwaPerp(address _rwaPerp) external onlyOwner {
        if (_rwaPerp == address(0)) revert InvalidAddress();
        rwaPerp = IRWAPerpetualTrading(_rwaPerp);
    }

    function transferOwnership(address _newOwner) external onlyOwner {
        if (_newOwner == address(0)) revert InvalidAddress();
        owner = _newOwner;
    }

    // ============ Internal Functions ============

    function _calculateFollowerMargin(
        uint256 _leaderMargin,
        uint256 _allocationAmount,
        uint256 _maxPositionSize
    ) internal pure returns (uint256) {
        // Use allocation amount directly, capped by max position size
        uint256 margin = _allocationAmount;

        // If leader's margin is smaller, scale down proportionally
        if (_leaderMargin < _allocationAmount) {
            margin = _leaderMargin;
        }

        // Apply max position size cap if set
        if (_maxPositionSize > 0 && margin > _maxPositionSize) {
            margin = _maxPositionSize;
        }

        return margin;
    }

    function _safeTransfer(address _to, uint256 _amount) internal {
        (bool success,) = payable(_to).call{value: _amount}("");
        if (!success) revert TransferFailed();
    }

    // ============ Receive ============

    receive() external payable {}
}

