        uint256 _creatorAllocationBps,
        string memory _website,
        string memory _twitter,
        string memory _telegram
    ) public payable returns (address tokenAddress) {
        // Check minting fee
        require(msg.value >= mintingFee, "MemeTokenFactoryV3: insufficient minting fee");

        // Validate inputs
        require(bytes(_name).length > 0, "MemeTokenFactoryV3: name cannot be empty");
        require(bytes(_symbol).length > 0, "MemeTokenFactoryV3: symbol cannot be empty");
        require(_totalSupply > 0, "MemeTokenFactoryV3: total supply must be greater than 0");
        require(bytes(_imageHash).length > 0, "MemeTokenFactoryV3: image hash cannot be empty");
        require(
            _creatorAllocationBps >= 100 && _creatorAllocationBps <= 1000,
            "MemeTokenFactoryV3: allocation must be 1-10%"
        );

        // Calculate creator amount
        uint256 creatorAmount = (_totalSupply * _creatorAllocationBps) / 10000;

        // Deploy new MemeTokenV2 with split distribution and social links
        MemeTokenV2 newToken = new MemeTokenV2(
            _name,
            _symbol,
            _totalSupply,
            _imageHash,
            msg.sender,         // creator
            creatorAmount,      // creator's allocation
            bondingCurveMarket, // curve gets the rest
            _website,
            _twitter,
            _telegram
        );

        tokenAddress = address(newToken);

        // Initialize bonding curve for this token
        BondingCurveMarket(payable(bondingCurveMarket)).initializeCurve(
            tokenAddress,
            msg.sender,
            _creatorAllocationBps,
            _totalSupply
        );

        // Store token info
        tokenInfo[tokenAddress] = TokenInfo({
            tokenAddress: tokenAddress,
            creator: msg.sender,
            name: _name,
            symbol: _symbol,
            totalSupply: _totalSupply,
            imageHash: _imageHash,
            creatorAllocationBps: _creatorAllocationBps,
            createdAt: block.timestamp,
            website: _website,
            twitter: _twitter,
            telegram: _telegram
        });

        // Add to arrays
        allTokens.push(tokenAddress);
        creatorTokens[msg.sender].push(tokenAddress);

        // Refund excess payment
        if (msg.value > mintingFee) {
            payable(msg.sender).transfer(msg.value - mintingFee);
        }

        emit TokenCreated(
            tokenAddress,
            msg.sender,
            _name,
            _symbol,
            _totalSupply,
            _imageHash,
            _creatorAllocationBps,
            block.timestamp,
            _website,
            _twitter,
            _telegram
        );

        return tokenAddress;
    }

    /**
     * @dev Update social links for a token (only token creator can update)
     * @param _tokenAddress Token address to update
     * @param _website New website URL
     * @param _twitter New Twitter handle
     * @param _telegram New Telegram handle
     */
    function updateSocialLinks(
        address _tokenAddress,
        string memory _website,
        string memory _twitter,
        string memory _telegram
    ) external {
        require(
            tokenInfo[_tokenAddress].tokenAddress != address(0),
            "MemeTokenFactoryV3: token does not exist"
        );
        require(
            tokenInfo[_tokenAddress].creator == msg.sender,
            "MemeTokenFactoryV3: only creator can update"
        );

        tokenInfo[_tokenAddress].website = _website;
        tokenInfo[_tokenAddress].twitter = _twitter;
        tokenInfo[_tokenAddress].telegram = _telegram;

        // Also update in the token contract
        MemeTokenV2(_tokenAddress).updateSocialLinks(_website, _twitter, _telegram);

        emit SocialLinksUpdated(_tokenAddress, _website, _twitter, _telegram);
    }

    /**
     * @dev Get total number of tokens created
     * @return Total count of tokens
     */
    function getTokenCount() public view returns (uint256) {
        return allTokens.length;
    }

    /**
     * @dev Get all token addresses
     * @return Array of all token addresses
     */
    function getAllTokens() public view returns (address[] memory) {
        return allTokens;
    }

    /**
     * @dev Get tokens created by a specific address
     * @param _creator Creator address
     * @return Array of token addresses created by the address
     */
    function getTokensByCreator(address _creator) public view returns (address[] memory) {
        return creatorTokens[_creator];
    }

    /**
     * @dev Get token info by address
     * @param _tokenAddress Token contract address
     * @return TokenInfo struct with token metadata
     */
    function getTokenInfo(address _tokenAddress) public view returns (TokenInfo memory) {
        require(
            tokenInfo[_tokenAddress].tokenAddress != address(0),
            "MemeTokenFactoryV3: token does not exist"
        );
        return tokenInfo[_tokenAddress];
    }

    /**
     * @dev Get multiple token infos
     * @param _tokenAddresses Array of token addresses
     * @return Array of TokenInfo structs
     */
    function getMultipleTokenInfos(
        address[] memory _tokenAddresses
    ) public view returns (TokenInfo[] memory) {
        TokenInfo[] memory infos = new TokenInfo[](_tokenAddresses.length);
        for (uint256 i = 0; i < _tokenAddresses.length; i++) {
            infos[i] = tokenInfo[_tokenAddresses[i]];
        }
        return infos;
    }

    /**
     * @dev Get social links for a token
     * @param _tokenAddress Token address
     * @return website Website URL
     * @return twitter Twitter handle
     * @return telegram Telegram handle
     */
    function getSocialLinks(address _tokenAddress) public view returns (
        string memory website,
        string memory twitter,
        string memory telegram
    ) {
        require(
            tokenInfo[_tokenAddress].tokenAddress != address(0),
            "MemeTokenFactoryV3: token does not exist"
        );
        TokenInfo memory info = tokenInfo[_tokenAddress];
        return (info.website, info.twitter, info.telegram);
    }

    /**
     * @dev Update minting fee (only owner)
     * @param _newFee New minting fee in wei
     */
    function setMintingFee(uint256 _newFee) public onlyOwner {
        uint256 oldFee = mintingFee;
        mintingFee = _newFee;
        emit MintingFeeUpdated(oldFee, _newFee);
    }

    /**
     * @dev Update bonding curve market address (only owner)
     * @param _newMarket New market address
     */
    function setBondingCurveMarket(address _newMarket) public onlyOwner {
        require(_newMarket != address(0), "MemeTokenFactoryV3: invalid market");
        address oldMarket = bondingCurveMarket;
        bondingCurveMarket = _newMarket;
        emit BondingCurveMarketUpdated(oldMarket, _newMarket);
    }

    /**
     * @dev Transfer ownership (only owner)
     * @param _newOwner New owner address
     */
    function transferOwnership(address _newOwner) public onlyOwner {
        require(_newOwner != address(0), "MemeTokenFactoryV3: new owner is zero address");
        address oldOwner = owner;
        owner = _newOwner;
        emit OwnershipTransferred(oldOwner, _newOwner);
    }

    /**
     * @dev Withdraw collected fees to treasury
     */
    function withdrawFees() external {
        uint256 balance = address(this).balance;
        require(balance > 0, "MemeTokenFactoryV3: no fees to withdraw");
        payable(TREASURY).transfer(balance);
    }

    /**
     * @dev Get contract balance
     * @return Balance in wei
     */
    function getContractBalance() public view returns (uint256) {
        return address(this).balance;
    }
}

project/contracts/MemeTokenV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title MemeTokenV2
 * @dev ERC20 token with IPFS image hash storage and social links for meme tokens
 * @notice This contract allows minting tokens with metadata including IPFS image hash and social links
 */
contract MemeTokenV2 {
    // Token metadata
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public totalSupply;

    // IPFS image hash (CID - Content Identifier)
    string public imageHash;

    // Token creator
    address public creator;

    // Factory address (for authorized updates)
    address public factory;

    // Creation timestamp
    uint256 public createdAt;

    // Social links (optional)
    string public website;
    string public twitter;
    string public telegram;

    // Balances mapping
    mapping(address => uint256) public balanceOf;

    // Allowances mapping
    mapping(address => mapping(address => uint256)) public allowance;

    // Events
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event TokenMinted(
        address indexed token,
        address indexed creator,
        string name,
        string symbol,
        uint256 totalSupply,
        string imageHash,
        string website,
        string twitter,
        string telegram
    );
    event SocialLinksUpdated(string website, string twitter, string telegram);

    /**
     * @dev Constructor to create a new MemeTokenV2 with split distribution and social links
     * @param _name Token name
     * @param _symbol Token symbol
     * @param _totalSupply Initial total supply
     * @param _imageHash IPFS hash (CID) of the token image
     * @param _creator Address that created this token
     * @param _creatorAmount Amount to mint to creator (use _totalSupply for 100%)
     * @param _curveMarket Address of bonding curve market (use address(0) for legacy 100% to creator)
     * @param _website Optional website URL
     * @param _twitter Optional Twitter/X handle
     * @param _telegram Optional Telegram handle
     */
    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _totalSupply,
        string memory _imageHash,
        address _creator,
        uint256 _creatorAmount,
        address _curveMarket,
        string memory _website,
        string memory _twitter,
        string memory _telegram
    ) {
        require(bytes(_name).length > 0, "MemeTokenV2: name cannot be empty");
        require(bytes(_symbol).length > 0, "MemeTokenV2: symbol cannot be empty");
        require(_totalSupply > 0, "MemeTokenV2: total supply must be greater than 0");
        require(bytes(_imageHash).length > 0, "MemeTokenV2: image hash cannot be empty");
        require(_creator != address(0), "MemeTokenV2: creator cannot be zero address");
        require(_creatorAmount <= _totalSupply, "MemeTokenV2: creator amount exceeds supply");

        name = _name;
        symbol = _symbol;
        totalSupply = _totalSupply;
        imageHash = _imageHash;
        creator = _creator;
        factory = msg.sender; // Factory is the deployer
        createdAt = block.timestamp;

        // Set social links (can be empty)
        website = _website;
        twitter = _twitter;
        telegram = _telegram;

        // Split distribution: creator gets their allocation
        balanceOf[_creator] = _creatorAmount;
        emit Transfer(address(0), _creator, _creatorAmount);

        // Rest goes to bonding curve market (if provided)
        uint256 curveAmount = _totalSupply - _creatorAmount;
        if (_curveMarket != address(0) && curveAmount > 0) {
            balanceOf[_curveMarket] = curveAmount;
            emit Transfer(address(0), _curveMarket, curveAmount);
        }

        emit TokenMinted(
            address(this),
            _creator,
            _name,
            _symbol,
            _totalSupply,
            _imageHash,
            _website,
            _twitter,
            _telegram
        );
    }

    /**
     * @dev Update social links (only factory or creator can call)
     * @param _website New website URL
     * @param _twitter New Twitter handle
     * @param _telegram New Telegram handle
     */
    function updateSocialLinks(
        string memory _website,
        string memory _twitter,
        string memory _telegram
    ) external {
        require(
            msg.sender == factory || msg.sender == creator,
            "MemeTokenV2: only factory or creator can update"
        );

        website = _website;
        twitter = _twitter;
        telegram = _telegram;

        emit SocialLinksUpdated(_website, _twitter, _telegram);
    }

    /**
     * @dev Transfer tokens to a specified address
     * @param _to Address to transfer to
     * @param _value Amount of tokens to transfer
     * @return success Boolean indicating if the transfer was successful
     */
    function transfer(address _to, uint256 _value) public returns (bool success) {
        require(_to != address(0), "MemeTokenV2: transfer to zero address");
        require(balanceOf[msg.sender] >= _value, "MemeTokenV2: insufficient balance");

        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;

        emit Transfer(msg.sender, _to, _value);
        return true;
    }

    /**
     * @dev Transfer tokens from one address to another (requires approval)
     * @param _from Address to transfer from
     * @param _to Address to transfer to
     * @param _value Amount of tokens to transfer
     * @return success Boolean indicating if the transfer was successful
     */
    function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
        require(_to != address(0), "MemeTokenV2: transfer to zero address");
        require(balanceOf[_from] >= _value, "MemeTokenV2: insufficient balance");
        require(allowance[_from][msg.sender] >= _value, "MemeTokenV2: insufficient allowance");

        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
        allowance[_from][msg.sender] -= _value;

        emit Transfer(_from, _to, _value);
        return true;
    }

    /**
     * @dev Approve spender to transfer tokens on behalf of owner
     * @param _spender Address to approve
     * @param _value Amount of tokens to approve
     * @return success Boolean indicating if the approval was successful
     */
    function approve(address _spender, uint256 _value) public returns (bool success) {
        require(_spender != address(0), "MemeTokenV2: approve to zero address");

        allowance[msg.sender][_spender] = _value;
        emit Approval(msg.sender, _spender, _value);
        return true;
    }

    /**
     * @dev Get token metadata
     * @return _name Token name
     * @return _symbol Token symbol
     * @return _totalSupply Total supply
     * @return _imageHash IPFS image hash
     * @return _creator Creator address
     * @return _createdAt Creation timestamp
     */
    function getMetadata() public view returns (
        string memory _name,
        string memory _symbol,
        uint256 _totalSupply,
        string memory _imageHash,
        address _creator,
        uint256 _createdAt
    ) {
        return (name, symbol, totalSupply, imageHash, creator, createdAt);
    }

    /**
     * @dev Get social links
     * @return _website Website URL
     * @return _twitter Twitter handle
     * @return _telegram Telegram handle
     */
    function getSocialLinks() public view returns (
        string memory _website,
        string memory _twitter,
        string memory _telegram
    ) {
        return (website, twitter, telegram);
    }

    /**
     * @dev Get IPFS image URL (constructs full IPFS URL)
     * @return Full IPFS URL for the image
     */
    function getImageURL() public view returns (string memory) {
        return string(abi.encodePacked("https://ipfs.io/ipfs/", imageHash));
    }
}

project/contracts/PerpetualTrading.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@pythnetwork/pyth-sdk-solidity/IPyth.sol";
import "@pythnetwork/pyth-sdk-solidity/PythStructs.sol";

// Interface for BondingCurveMarket
interface IBondingCurveMarket {
    function isListed(address token) external view returns (bool);
    function getCurrentPrice(address token) external view returns (uint256);
}

/**
 * @title PerpetualTrading
 * @dev Perpetual futures trading contract with Pyth Network price feeds
 * @notice Supports long/short positions on listed tokens with leverage
 */
contract PerpetualTrading {
    // Pyth Network oracle
    IPyth public pyth;

    // Bonding curve market for price feeds
    IBondingCurveMarket public bondingCurveMarket;

    // Owner
    address public owner;

    // Protocol treasury (receives trading fees)
    address public constant TREASURY = 0x844dAea3090440468AC4B0654743ae10B99083cC;

    // Trading fee (basis points, e.g., 5 = 0.05%)
    uint256 public tradingFeeBps = 5; // 0.05%

    // Maximum leverage (e.g., 100 = 100x)
    uint256 public maxLeverage = 100;

    // Minimum margin (e.g., 1000 = 0.1% of position size)
    uint256 public minMarginBps = 1000; // 1% = 100 bps, so 1000 = 10%

    // Position struct
    struct Position {
        address user;
        address token; // Token address (0x0 for native token)
        bool isLong; // true = long, false = short
        uint256 size; // Position size in USD (scaled)
        uint256 margin; // Margin deposited
        uint256 leverage; // Leverage multiplier (e.g., 10 = 10x)
        uint256 entryPrice; // Entry price in USD (scaled)
        uint256 entryTime; // Block timestamp
        uint256 lastFundingTime; // Last funding payment time
        bool isOpen;
    }

    // Position storage
    mapping(uint256 => Position) public positions;
    mapping(address => uint256[]) public userPositions;
    uint256 public nextPositionId;

    // Price storage for meme tokens (fallback when Pyth not available)
    mapping(address => uint256) public lastTradePrice; // Price in USD (scaled)
    mapping(address => uint256) public lastPriceUpdate;

    // Pyth price feed IDs mapping (token address => price feed ID)
    mapping(address => bytes32) public priceFeedIds;

    // Events
    event PositionOpened(
        uint256 indexed positionId,
        address indexed user,
        address indexed token,
        bool isLong,
        uint256 size,
        uint256 margin,
        uint256 leverage,
        uint256 entryPrice
    );

    event PositionClosed(
        uint256 indexed positionId,
        address indexed user,
        uint256 pnl,
        uint256 exitPrice
    );

    event PositionLiquidated(
        uint256 indexed positionId,
        address indexed user,
        uint256 liquidationPrice
    );

    event PriceUpdated(address indexed token, uint256 price);
    event BondingCurveMarketUpdated(address indexed oldMarket, address indexed newMarket);

    modifier onlyOwner() {
        require(msg.sender == owner, "PerpetualTrading: caller is not owner");
        _;
    }

    modifier onlyListedTokens(address _token) {
        require(
            address(bondingCurveMarket) != address(0) &&
            bondingCurveMarket.isListed(_token),
            "PerpetualTrading: token not listed on bonding curve"
        );
        _;
    }

    /**
     * @dev Constructor
     * @param _pyth Pyth Network oracle address
     */
    constructor(address _pyth) {
        // Allow zero address for testing (will use fallback mechanism only)
        if (_pyth != address(0)) {
            pyth = IPyth(_pyth);
        }
        owner = msg.sender;
    }

    /**
     * @dev Set bonding curve market address
     * @param _bondingCurveMarket BondingCurveMarket contract address
     */
    function setBondingCurveMarket(address _bondingCurveMarket) public onlyOwner {
        address oldMarket = address(bondingCurveMarket);
        bondingCurveMarket = IBondingCurveMarket(_bondingCurveMarket);
        emit BondingCurveMarketUpdated(oldMarket, _bondingCurveMarket);
    }

    /**
     * @dev Set price feed ID for a token
     * @param _token Token address
     * @param _priceFeedId Pyth price feed ID (bytes32)
     */
    function setPriceFeedId(address _token, bytes32 _priceFeedId) public onlyOwner {
        priceFeedIds[_token] = _priceFeedId;
    }

    /**
     * @dev Get current price from bonding curve, Pyth, or fallback
     * @param _token Token address
     * @return currentPrice Price in USD (scaled by 1e8)
     * @return hasPrice Whether price is available
     */
    function getCurrentPrice(address _token) public view returns (uint256 currentPrice, bool hasPrice) {
        // Priority 1: Bonding curve market (for listed meme tokens)
        if (address(bondingCurveMarket) != address(0)) {
            try bondingCurveMarket.isListed(_token) returns (bool isListed) {
                if (isListed) {
                    try bondingCurveMarket.getCurrentPrice(_token) returns (uint256 curvePrice) {
                        if (curvePrice > 0) {
                            return (curvePrice, true);
                        }
                    } catch {
                        // Continue to other sources
                    }
                }
            } catch {
                // Continue to other sources
            }
        }

        // Priority 2: Pyth oracle (for major tokens with feeds)
        bytes32 feedId = priceFeedIds[_token];
        if (feedId != bytes32(0) && address(pyth) != address(0)) {
            try pyth.getPriceNoOlderThan(feedId, 60) returns (PythStructs.Price memory priceData) {
                if (priceData.price > 0) {
                    int256 expo = priceData.expo;
                    int64 priceValue = priceData.price;
                    uint256 normalizedPrice = uint256(uint64(priceValue));

                    if (expo < 0) {
                        normalizedPrice = normalizedPrice * (10 ** uint256(-expo)) * 1e8;
                    } else if (expo > 0) {
                        normalizedPrice = (normalizedPrice / (10 ** uint256(expo))) * 1e8;
                    } else {
                        normalizedPrice = normalizedPrice * 1e8;
                    }

                    return (normalizedPrice, true);
                }
            } catch {
                // Pyth call failed, try fallback
            }
        }

        // Priority 3: Last trade price fallback (legacy)
        if (lastTradePrice[_token] > 0) {
            return (lastTradePrice[_token], true);
        }

        return (0, false);
    }

    /**
     * @dev Update price for meme token (called on first trade)
     * @param _token Token address
     * @param _price Price in USD (scaled by 1e8)
     */
    function updateMemeTokenPrice(address _token, uint256 _price) public {
        require(_price > 0, "PerpetualTrading: invalid price");
        lastTradePrice[_token] = _price;
        lastPriceUpdate[_token] = block.timestamp;
        emit PriceUpdated(_token, _price);
    }

    /**
     * @dev Open a position
     * @param _token Token address (0x0 for native token)
     * @param _isLong true for long, false for short
     * @param _margin Margin amount in wei
     * @param _leverage Leverage multiplier (e.g., 10 = 10x)
     */
    function openPosition(
        address _token,
        bool _isLong,
        uint256 _margin,
        uint256 _leverage
    ) public payable onlyListedTokens(_token) returns (uint256 positionId) {
        require(_leverage > 0 && _leverage <= maxLeverage, "PerpetualTrading: invalid leverage");
        require(_margin > 0, "PerpetualTrading: margin must be > 0");

        uint256 marginAmount = msg.value > 0 ? msg.value : _margin;
        require(marginAmount > 0, "PerpetualTrading: no margin provided");

        // Get current price
        (uint256 currentPrice, bool hasPrice) = getCurrentPrice(_token);
        require(hasPrice && currentPrice > 0, "PerpetualTrading: price not available");

        // Calculate position size
        uint256 positionSize = (marginAmount * _leverage * currentPrice) / 1e18;
        require(positionSize > 0, "PerpetualTrading: position size too small");

        // Check minimum margin requirement
        uint256 minMargin = (positionSize * minMarginBps) / 10000;
        require(marginAmount >= minMargin, "PerpetualTrading: insufficient margin");

        // Calculate trading fee
        uint256 fee = (positionSize * tradingFeeBps) / 10000;
        require(marginAmount > fee, "PerpetualTrading: margin too small for fee");

        // Create position
        positionId = nextPositionId++;
        positions[positionId] = Position({
            user: msg.sender,
            token: _token,
            isLong: _isLong,
            size: positionSize,
            margin: marginAmount - fee,
            leverage: _leverage,
            entryPrice: currentPrice,
            entryTime: block.timestamp,
            lastFundingTime: block.timestamp,
            isOpen: true
        });

        userPositions[msg.sender].push(positionId);

        emit PositionOpened(
            positionId,
            msg.sender,
            _token,
            _isLong,
            positionSize,
            marginAmount - fee,
            _leverage,
            currentPrice
        );

        return positionId;
    }

    /**
     * @dev Close a position
     * @param _positionId Position ID
     */
    function closePosition(uint256 _positionId) public {
        Position storage position = positions[_positionId];
        require(position.isOpen, "PerpetualTrading: position not open");
        require(position.user == msg.sender, "PerpetualTrading: not position owner");

        // Get current price
        (uint256 currentPrice, bool hasPrice) = getCurrentPrice(position.token);
        require(hasPrice && currentPrice > 0, "PerpetualTrading: price not available");

        // Calculate PnL (signed)
        (uint256 pnl, bool isProfit) = getPositionPnL(_positionId);

        // Calculate trading fee
        uint256 fee = (position.size * tradingFeeBps) / 10000;

        // Calculate total payout
        uint256 totalPayout;
        if (isProfit) {
            // Profit: margin + profit - fee
            if (pnl > fee) {
                totalPayout = position.margin + pnl - fee;
            } else {
                // Fee exceeds profit
                if (position.margin + pnl > fee) {
                    totalPayout = position.margin + pnl - fee;
                } else {
                    totalPayout = 0;
                }
            }
        } else {
            // Loss: margin - loss - fee
            if (position.margin > pnl + fee) {
                totalPayout = position.margin - pnl - fee;
            } else {
                totalPayout = 0; // Total loss
            }
        }

        // Update price for meme tokens
        if (position.token != address(0) && priceFeedIds[position.token] == bytes32(0)) {
            lastTradePrice[position.token] = currentPrice;
            lastPriceUpdate[position.token] = block.timestamp;
        }

        // Close position
        position.isOpen = false;

        // Transfer payout
        if (totalPayout > 0) {
            payable(msg.sender).transfer(totalPayout);
        }

        emit PositionClosed(_positionId, msg.sender, pnl, currentPrice);
    }


    /**
     * @dev Get position PnL (signed)
     * @param _positionId Position ID
     * @return pnl Profit (positive) or loss (negative, as uint256 representing absolute value)
     * @return isProfit Whether PnL is profit
     */
    function getPositionPnL(uint256 _positionId) public view returns (uint256 pnl, bool isProfit) {
        Position memory position = positions[_positionId];
        require(position.isOpen, "PerpetualTrading: position not open");

        (uint256 currentPrice, bool hasPrice) = getCurrentPrice(position.token);
        require(hasPrice, "PerpetualTrading: price not available");

        if (position.isLong) {
            if (currentPrice >= position.entryPrice) {
                pnl = ((currentPrice - position.entryPrice) * position.size) / position.entryPrice;
                isProfit = true;
            } else {
                pnl = ((position.entryPrice - currentPrice) * position.size) / position.entryPrice;
                isProfit = false;
            }
        } else {
            if (currentPrice <= position.entryPrice) {
                pnl = ((position.entryPrice - currentPrice) * position.size) / position.entryPrice;
                isProfit = true;
            } else {
                pnl = ((currentPrice - position.entryPrice) * position.size) / position.entryPrice;
                isProfit = false;
            }
        }

        return (pnl, isProfit);
    }

    /**
     * @dev Get liquidation price for a position
     * @param _positionId Position ID
     * @return liquidationPrice Price at which position would be liquidated
     */
    function getLiquidationPrice(uint256 _positionId) public view returns (uint256 liquidationPrice) {
        Position memory position = positions[_positionId];
        require(position.isOpen, "PerpetualTrading: position not open");

        // Liquidation when margin is lost (simplified: when PnL = -margin)
        // For long: entryPrice * (1 - margin/size)
        // For short: entryPrice * (1 + margin/size)

        if (position.isLong) {
            // Long liquidates when price drops
            uint256 marginRatio = (position.margin * 1e18) / position.size;
            liquidationPrice = position.entryPrice * (1e18 - marginRatio) / 1e18;
        } else {
            // Short liquidates when price rises
            uint256 marginRatio = (position.margin * 1e18) / position.size;
            liquidationPrice = position.entryPrice * (1e18 + marginRatio) / 1e18;
        }

        return liquidationPrice;
    }

    /**
     * @dev Check if position should be liquidated
     * @param _positionId Position ID
     * @return Whether position should be liquidated
     */
    function shouldLiquidate(uint256 _positionId) public view returns (bool) {
        Position memory position = positions[_positionId];
        if (!position.isOpen) return false;

        (uint256 currentPrice, bool hasPrice) = getCurrentPrice(position.token);
        if (!hasPrice) return false;

        uint256 liquidationPrice = getLiquidationPrice(_positionId);

        if (position.isLong) {
            return currentPrice <= liquidationPrice;
        } else {
            return currentPrice >= liquidationPrice;
        }
    }

    /**
     * @dev Liquidate a position
     * @param _positionId Position ID
     */
    function liquidatePosition(uint256 _positionId) public {
        require(shouldLiquidate(_positionId), "PerpetualTrading: position not liquidatable");

        Position storage position = positions[_positionId];
        position.isOpen = false;

        (uint256 currentPrice, ) = getCurrentPrice(position.token);

        // Liquidator gets a small reward (5% of margin)
        uint256 reward = position.margin / 20;
        if (reward > 0) {
            payable(msg.sender).transfer(reward);
        }

        emit PositionLiquidated(_positionId, position.user, currentPrice);
    }

    /**
     * @dev Get user positions
     * @param _user User address
     * @return positionIds Array of position IDs
     */
    function getUserPositions(address _user) public view returns (uint256[] memory) {
        return userPositions[_user];
    }

    /**
     * @dev Get position details
     * @param _positionId Position ID
     * @return position Position struct
     */
    function getPosition(uint256 _positionId) public view returns (Position memory) {
        return positions[_positionId];
    }

    /**
     * @dev Update trading fee
     * @param _newFeeBps New fee in basis points
     */
    function setTradingFee(uint256 _newFeeBps) public onlyOwner {
        require(_newFeeBps <= 1000, "PerpetualTrading: fee too high"); // Max 10%
        tradingFeeBps = _newFeeBps;
    }

    /**
     * @dev Update max leverage
     * @param _newMaxLeverage New max leverage
     */
    function setMaxLeverage(uint256 _newMaxLeverage) public onlyOwner {
        require(_newMaxLeverage > 0 && _newMaxLeverage <= 1000, "PerpetualTrading: invalid leverage");
        maxLeverage = _newMaxLeverage;
    }

    /**
     * @dev Withdraw contract balance to treasury
     */
    function withdrawFees() external {
        uint256 balance = address(this).balance;
        require(balance > 0, "PerpetualTrading: no fees to withdraw");
        payable(TREASURY).transfer(balance);
    }

    /**
     * @dev Receive function to accept native tokens
     */
    receive() external payable {}
}

