// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@pythnetwork/pyth-sdk-solidity/IPyth.sol";
import "@pythnetwork/pyth-sdk-solidity/PythStructs.sol";

/**
 * @title RWAPerpetualTrading
 * @dev Optimized perpetual futures trading for Real World Assets (RWA)
 * @notice Flexible design - new assets can be added without contract changes
 */
contract RWAPerpetualTrading {
    // ============ Constants ============

    uint256 private constant BASIS_POINTS = 10000;
    uint256 private constant PRICE_DECIMALS = 1e8;
    uint256 private constant MAX_FEE_BPS = 100; // Max 1%
    uint256 private constant MAX_LEVERAGE_CAP = 200;
    uint256 private constant LIQUIDATION_THRESHOLD = 5; // 5% remaining margin
    uint256 private constant PRICE_STALENESS = 300; // 5 minutes

    // ============ State Variables ============

    IPyth public immutable pyth;
    address public owner;
    address public treasury;

    uint256 public tradingFeeBps = 10; // 0.1%
    uint256 public defaultMaxLeverage = 50;
    uint256 public minMargin = 0.001 ether;

    uint256 public nextPositionId;
    uint256 public totalAssets;

    // ============ Structs ============

    struct AssetConfig {
        bytes32 priceFeedId;    // Pyth price feed ID
        uint256 maxLeverage;    // Asset-specific max leverage
        uint256 minMargin;      // Asset-specific min margin (0 = use global)
        bool isActive;          // Trading enabled flag
        string symbol;          // e.g., "XAU/USD"
    }

    struct Position {
        address user;
        bytes32 assetId;
        uint128 margin;         // Using uint128 to pack storage
        uint128 size;           // Position size in USD (scaled by 1e18)
        int64 entryPrice;
        int32 entryExpo;
        uint32 leverage;
        uint32 entryTime;
        bool isLong;
        bool isOpen;
    }

    // ============ Storage ============

    // Asset ID (keccak256 of string) => Asset config
    mapping(bytes32 => AssetConfig) public assets;

    // Array of asset IDs for enumeration
    bytes32[] public assetList;

    // Position ID => Position
    mapping(uint256 => Position) public positions;

    // User => Position IDs
    mapping(address => uint256[]) private _userPositions;

    // ============ Events ============

    event AssetAdded(
        bytes32 indexed assetId,
        string symbol,
        bytes32 priceFeedId,
        uint256 maxLeverage
    );

    event AssetUpdated(
        bytes32 indexed assetId,
        bool isActive,
        uint256 maxLeverage
    );

    event AssetRemoved(bytes32 indexed assetId);

    event PositionOpened(
        uint256 indexed positionId,
        address indexed user,
        bytes32 indexed assetId,
        bool isLong,
        uint256 size,
        uint256 margin,
        uint256 leverage,
        int64 entryPrice,
        int32 entryExpo
    );

    event PositionClosed(
        uint256 indexed positionId,
        address indexed user,
        bytes32 indexed assetId,
        int256 pnl,
        int64 exitPrice
    );

    event PositionLiquidated(
        uint256 indexed positionId,
        address indexed user,
        address indexed liquidator,
        int64 liquidationPrice
    );

    event ConfigUpdated(string param, uint256 value);
    event TreasuryUpdated(address newTreasury);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ============ Errors ============

    error NotOwner();
    error InvalidAddress();
    error AssetNotActive();
    error AssetAlreadyExists();
    error AssetNotFound();
    error InvalidLeverage();
    error InsufficientMargin();
    error PositionNotOpen();
    error NotPositionOwner();
    error PriceUnavailable();
    error NotLiquidatable();
    error InvalidFee();
    error TransferFailed();

    // ============ Modifiers ============

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyActiveAsset(bytes32 _assetId) {
        if (!assets[_assetId].isActive) revert AssetNotActive();
        _;
    }

    // ============ Constructor ============

    constructor(address _pyth, address _treasury) {
        if (_pyth == address(0)) revert InvalidAddress();

        pyth = IPyth(_pyth);
        owner = msg.sender;
        treasury = _treasury != address(0) ? _treasury : msg.sender;

        emit OwnershipTransferred(address(0), msg.sender);
    }

    // ============ Admin Functions ============

    /**
     * @dev Add a new tradeable asset
     * @param _id String identifier (e.g., "gold", "btcusd")
     * @param _symbol Display symbol (e.g., "XAU/USD")
     * @param _priceFeedId Pyth Network price feed ID
     * @param _maxLeverage Maximum leverage for this asset (0 = use default)
     */
    function addAsset(
        string calldata _id,
        string calldata _symbol,
        bytes32 _priceFeedId,
        uint256 _maxLeverage
    ) external onlyOwner {
        bytes32 assetId = keccak256(abi.encodePacked(_id));

        if (assets[assetId].priceFeedId != bytes32(0)) revert AssetAlreadyExists();
        if (_maxLeverage > MAX_LEVERAGE_CAP) revert InvalidLeverage();

        assets[assetId] = AssetConfig({
            priceFeedId: _priceFeedId,
            maxLeverage: _maxLeverage > 0 ? _maxLeverage : defaultMaxLeverage,
            minMargin: 0,
            isActive: true,
            symbol: _symbol
        });

        assetList.push(assetId);
        totalAssets++;

        emit AssetAdded(assetId, _symbol, _priceFeedId, _maxLeverage);
    }

    /**
     * @dev Add multiple assets in one transaction (gas efficient)
     */
    function addAssetsBatch(
        string[] calldata _ids,
        string[] calldata _symbols,
        bytes32[] calldata _priceFeedIds,
        uint256[] calldata _maxLeverages
    ) external onlyOwner {
        uint256 len = _ids.length;
        require(
            len == _symbols.length &&
            len == _priceFeedIds.length &&
            len == _maxLeverages.length,
            "Length mismatch"
        );

        for (uint256 i = 0; i < len;) {
            bytes32 assetId = keccak256(abi.encodePacked(_ids[i]));

            if (assets[assetId].priceFeedId == bytes32(0)) {
                uint256 maxLev = _maxLeverages[i] > 0 ? _maxLeverages[i] : defaultMaxLeverage;
                if (maxLev > MAX_LEVERAGE_CAP) maxLev = MAX_LEVERAGE_CAP;

                assets[assetId] = AssetConfig({
                    priceFeedId: _priceFeedIds[i],
                    maxLeverage: maxLev,
                    minMargin: 0,
                    isActive: true,
                    symbol: _symbols[i]
                });

                assetList.push(assetId);
                totalAssets++;

                emit AssetAdded(assetId, _symbols[i], _priceFeedIds[i], maxLev);
            }

            unchecked { ++i; }
        }
    }

    /**
     * @dev Update asset configuration
     */
    function updateAsset(
        bytes32 _assetId,
        bool _isActive,
        uint256 _maxLeverage,
        uint256 _minMargin
    ) external onlyOwner {
        if (assets[_assetId].priceFeedId == bytes32(0)) revert AssetNotFound();
        if (_maxLeverage > MAX_LEVERAGE_CAP) revert InvalidLeverage();

        AssetConfig storage asset = assets[_assetId];
        asset.isActive = _isActive;
        if (_maxLeverage > 0) asset.maxLeverage = _maxLeverage;
        asset.minMargin = _minMargin;

        emit AssetUpdated(_assetId, _isActive, _maxLeverage);
    }

    /**
     * @dev Update price feed for an asset
     */
    function updatePriceFeed(bytes32 _assetId, bytes32 _newPriceFeedId) external onlyOwner {
        if (assets[_assetId].priceFeedId == bytes32(0)) revert AssetNotFound();
        assets[_assetId].priceFeedId = _newPriceFeedId;
    }

    function setTradingFee(uint256 _newFeeBps) external onlyOwner {
        if (_newFeeBps > MAX_FEE_BPS) revert InvalidFee();
        tradingFeeBps = _newFeeBps;
        emit ConfigUpdated("tradingFeeBps", _newFeeBps);
    }

    function setDefaultMaxLeverage(uint256 _newMaxLeverage) external onlyOwner {
        if (_newMaxLeverage == 0 || _newMaxLeverage > MAX_LEVERAGE_CAP) revert InvalidLeverage();
        defaultMaxLeverage = _newMaxLeverage;
        emit ConfigUpdated("defaultMaxLeverage", _newMaxLeverage);
    }

    function setMinMargin(uint256 _newMinMargin) external onlyOwner {
        minMargin = _newMinMargin;
        emit ConfigUpdated("minMargin", _newMinMargin);
    }

    function setTreasury(address _treasury) external onlyOwner {
        if (_treasury == address(0)) revert InvalidAddress();
        treasury = _treasury;
        emit TreasuryUpdated(_treasury);
    }

    function transferOwnership(address _newOwner) external onlyOwner {
        if (_newOwner == address(0)) revert InvalidAddress();
        emit OwnershipTransferred(owner, _newOwner);
        owner = _newOwner;
    }

    // ============ Trading Functions ============

    /**
     * @dev Open a perpetual position
     * @param _assetId Asset identifier (keccak256 of string id)
     * @param _isLong true for long, false for short
     * @param _leverage Leverage multiplier
     * @param _priceUpdateData Pyth price update data (optional)
     */
    function openPosition(
        bytes32 _assetId,
        bool _isLong,
        uint256 _leverage,
        bytes[] calldata _priceUpdateData
    ) external payable onlyActiveAsset(_assetId) returns (uint256 positionId) {
        AssetConfig storage asset = assets[_assetId];

        // Validate leverage
        uint256 maxLev = asset.maxLeverage;
        if (_leverage == 0 || _leverage > maxLev) revert InvalidLeverage();

        // Update price if data provided
        uint256 pythFee = 0;
        if (_priceUpdateData.length > 0) {
            pythFee = pyth.getUpdateFee(_priceUpdateData);
            pyth.updatePriceFeeds{value: pythFee}(_priceUpdateData);
        }

        // Calculate margin
        uint256 margin = msg.value - pythFee;
        uint256 assetMinMargin = asset.minMargin > 0 ? asset.minMargin : minMargin;
        if (margin < assetMinMargin) revert InsufficientMargin();

        // Get current price
        (int64 currentPrice, int32 expo) = _getPrice(asset.priceFeedId);
        if (currentPrice <= 0) revert PriceUnavailable();

        // Calculate position size
        uint256 priceUSD = _normalizePrice(currentPrice, expo);
        uint256 positionSize = (margin * _leverage * priceUSD) / 1e18;

        // Deduct trading fee
        uint256 fee = (margin * tradingFeeBps) / BASIS_POINTS;
        uint256 marginAfterFee = margin - fee;

        // Transfer fee
        if (fee > 0) {
            _safeTransfer(treasury, fee);
        }

        // Create position
        positionId = nextPositionId++;
        positions[positionId] = Position({
            user: msg.sender,
            assetId: _assetId,
            margin: uint128(marginAfterFee),
            size: uint128(positionSize),
            entryPrice: currentPrice,
            entryExpo: expo,
            leverage: uint32(_leverage),
            entryTime: uint32(block.timestamp),
            isLong: _isLong,
            isOpen: true
        });

        _userPositions[msg.sender].push(positionId);

        emit PositionOpened(
            positionId,
            msg.sender,
            _assetId,
            _isLong,
            positionSize,
            marginAfterFee,
            _leverage,
            currentPrice,
            expo
        );
    }

    /**
     * @dev Close a position
     */
    function closePosition(
        uint256 _positionId,
        bytes[] calldata _priceUpdateData
    ) external payable {
        Position storage position = positions[_positionId];
        if (!position.isOpen) revert PositionNotOpen();
        if (position.user != msg.sender) revert NotPositionOwner();

        // Update price if data provided
        if (_priceUpdateData.length > 0) {
            uint256 pythFee = pyth.getUpdateFee(_priceUpdateData);
            pyth.updatePriceFeeds{value: pythFee}(_priceUpdateData);
        }

        // Get current price
        bytes32 priceFeedId = assets[position.assetId].priceFeedId;
        (int64 currentPrice,) = _getPrice(priceFeedId);
        if (currentPrice <= 0) revert PriceUnavailable();

        // Calculate PnL
        (int256 pnl,) = _calculatePnL(position, currentPrice);

        // Calculate exit fee
        uint256 exitFee = (uint256(position.margin) * tradingFeeBps) / BASIS_POINTS;

        // Calculate payout
        int256 payout = int256(uint256(position.margin)) + pnl - int256(exitFee);

        // Close position
        position.isOpen = false;

        // Transfer payout
        if (payout > 0) {
            _safeTransfer(msg.sender, uint256(payout));
        }

        // Transfer exit fee
        if (exitFee > 0 && address(this).balance >= exitFee) {
            _safeTransfer(treasury, exitFee);
        }

        emit PositionClosed(_positionId, msg.sender, position.assetId, pnl, currentPrice);
    }

    /**
     * @dev Liquidate an underwater position
     */
    function liquidate(
        uint256 _positionId,
        bytes[] calldata _priceUpdateData
    ) external payable {
        Position storage position = positions[_positionId];
        if (!position.isOpen) revert PositionNotOpen();

        // Update price if data provided
        if (_priceUpdateData.length > 0) {
            uint256 pythFee = pyth.getUpdateFee(_priceUpdateData);
            pyth.updatePriceFeeds{value: pythFee}(_priceUpdateData);
        }

        // Get current price
        bytes32 priceFeedId = assets[position.assetId].priceFeedId;
        (int64 currentPrice,) = _getPrice(priceFeedId);
        if (currentPrice <= 0) revert PriceUnavailable();

        // Check liquidation condition
        (int256 pnl,) = _calculatePnL(position, currentPrice);
        int256 remainingMargin = int256(uint256(position.margin)) + pnl;
        int256 liquidationThreshold = int256(uint256(position.margin)) * int256(LIQUIDATION_THRESHOLD) / 100;

        if (remainingMargin > liquidationThreshold) revert NotLiquidatable();

        // Close position
        position.isOpen = false;

        // Liquidator reward: 5% of remaining margin (if positive)
        if (remainingMargin > 0) {
            uint256 reward = uint256(remainingMargin) / 20;
            if (reward > 0) {
                _safeTransfer(msg.sender, reward);
            }
        }

        emit PositionLiquidated(_positionId, position.user, msg.sender, currentPrice);
    }

    // ============ View Functions ============

    function getPrice(bytes32 _assetId) external view returns (int64 price, int32 expo, uint256 timestamp) {
        AssetConfig storage asset = assets[_assetId];
        if (asset.priceFeedId == bytes32(0)) revert AssetNotFound();

        PythStructs.Price memory priceData = pyth.getPriceNoOlderThan(asset.priceFeedId, PRICE_STALENESS);
        return (priceData.price, priceData.expo, priceData.publishTime);
    }

    function getPriceUSD(bytes32 _assetId) external view returns (uint256) {
        AssetConfig storage asset = assets[_assetId];
        if (asset.priceFeedId == bytes32(0)) revert AssetNotFound();

        (int64 price, int32 expo) = _getPrice(asset.priceFeedId);
        return _normalizePrice(price, expo);
    }

    function getPositionPnL(uint256 _positionId) external view returns (int256 pnl, bool isProfit) {
        Position storage position = positions[_positionId];
        if (!position.isOpen) revert PositionNotOpen();

        bytes32 priceFeedId = assets[position.assetId].priceFeedId;
        (int64 currentPrice,) = _getPrice(priceFeedId);

        return _calculatePnL(position, currentPrice);
    }

    function getLiquidationPrice(uint256 _positionId) external view returns (int64) {
        Position storage position = positions[_positionId];
        if (!position.isOpen) revert PositionNotOpen();

        uint256 entryPriceAbs = uint256(uint64(position.entryPrice));
        uint256 marginRatio = (95 * 1e18) / (uint256(position.leverage) * 100);

        if (position.isLong) {
            return int64(uint64(entryPriceAbs * (1e18 - marginRatio) / 1e18));
        } else {
            return int64(uint64(entryPriceAbs * (1e18 + marginRatio) / 1e18));
        }
    }

    function shouldLiquidate(uint256 _positionId) external view returns (bool) {
        Position storage position = positions[_positionId];
        if (!position.isOpen) return false;

        bytes32 priceFeedId = assets[position.assetId].priceFeedId;
        (int64 currentPrice,) = _getPrice(priceFeedId);
        (int256 pnl,) = _calculatePnL(position, currentPrice);

        int256 remainingMargin = int256(uint256(position.margin)) + pnl;
        int256 liquidationThreshold = int256(uint256(position.margin)) * int256(LIQUIDATION_THRESHOLD) / 100;

        return remainingMargin <= liquidationThreshold;
    }

    function getUserPositions(address _user) external view returns (uint256[] memory) {
        return _userPositions[_user];
    }

    function getPosition(uint256 _positionId) external view returns (Position memory) {
        return positions[_positionId];
    }

    function getAsset(bytes32 _assetId) external view returns (AssetConfig memory) {
        return assets[_assetId];
    }

    function getAssetIds() external view returns (bytes32[] memory) {
        return assetList;
    }

    function getAllAssets() external view returns (bytes32[] memory ids, AssetConfig[] memory configs) {
        uint256 len = assetList.length;
        ids = assetList;
        configs = new AssetConfig[](len);

        for (uint256 i = 0; i < len;) {
            configs[i] = assets[assetList[i]];
            unchecked { ++i; }
        }
    }

    function getAssetId(string calldata _id) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(_id));
    }

    function isAssetActive(bytes32 _assetId) external view returns (bool) {
        return assets[_assetId].isActive;
    }

    // ============ Internal Functions ============

    function _getPrice(bytes32 _priceFeedId) internal view returns (int64 price, int32 expo) {
        PythStructs.Price memory priceData = pyth.getPriceNoOlderThan(_priceFeedId, PRICE_STALENESS);
        return (priceData.price, priceData.expo);
    }

    function _normalizePrice(int64 _price, int32 _expo) internal pure returns (uint256) {
        if (_price <= 0) return 0;

        uint256 normalizedPrice = uint256(uint64(_price));

        if (_expo < 0) {
            int32 absExpo = -_expo;
            if (absExpo > 8) {
                normalizedPrice = normalizedPrice / (10 ** uint32(absExpo - 8));
            } else {
                normalizedPrice = normalizedPrice * (10 ** uint32(8 - absExpo));
            }
        } else {
            normalizedPrice = normalizedPrice * (10 ** (8 + uint32(_expo)));
        }

        return normalizedPrice;
    }

    function _calculatePnL(Position storage _position, int64 _currentPrice) internal view returns (int256 pnl, bool isProfit) {
        int256 priceChange;

        if (_position.isLong) {
            priceChange = int256(uint256(uint64(_currentPrice))) - int256(uint256(uint64(_position.entryPrice)));
        } else {
            priceChange = int256(uint256(uint64(_position.entryPrice))) - int256(uint256(uint64(_currentPrice)));
        }

        pnl = (int256(uint256(_position.margin)) * int256(uint256(_position.leverage)) * priceChange) / int256(uint256(uint64(_position.entryPrice)));
        isProfit = pnl > 0;
    }

    function _safeTransfer(address _to, uint256 _amount) internal {
        (bool success,) = payable(_to).call{value: _amount}("");
        if (!success) revert TransferFailed();
    }

    // ============ Emergency Functions ============

    function emergencyWithdraw() external onlyOwner {
        _safeTransfer(owner, address(this).balance);
    }

    receive() external payable {}
}
